1	/**
2	 * Scans for issues past `dueAt` and emits `issue.overdue`, which the notification fan-out turns into alerts.
3	 *
4	 * Must call (do not reimplement): emit, shouldFilterArchived
5	 */
6	import { emit } from "@/lib/event-bus";
7	import { createLogger } from "@/lib/logger";
8	import { shouldFilterArchived } from "@/lib/soft-delete";
9	import * as issueRepo from "@/server/repositories/issue-repository";
10	import * as usageRepo from "@/server/repositories/usage-repository";
11	import { toIsoTimestamp } from "@/types/common";
12	import { runJob } from "./types";
13	import type { JobResult } from "@/server/jobs/types";
14	
15	/** How many organizations one pass sweeps. */
16	const ORG_BATCH = 50;
17	
18	/** Archived issues are never overdue — an archived issue has no due date. */
19	const LIVE_ONLY = {} as const;
20	
21	const logger = createLogger("overdue-issue-job");
22	
23	/**
24	 * Issues already announced this process's lifetime. A later sweep still
25	 * finds a still-open, still-overdue issue — this is what keeps the job from
26	 * re-emitting `issue.overdue` for it on every pass.
27	 */
28	const reported = new Set<string>();
29	
30	/** Test-only: clears the reported set so a fresh scenario starts empty. */
31	export function resetOverdueTracking(): void {
32	  reported.clear();
33	}
34	
35	/**
36	 * Publishes one `issue.overdue` per still-open, past-due issue. The job owns
37	 * no notification logic: it announces the fact, and whoever cares (in-app
