1	/**
2	 * Comment creation, edit window enforcement, mention extraction and soft delete.
3	 *
4	 * Must call (do not reimplement): assertCan, assertOrgScope, emit, archivePatch, consumeRateLimit
5	 */
6	import { emit } from "@/lib/event-bus";
7	import { resolveMentions } from "@/lib/mentions";
8	import { assertCan } from "@/lib/permissions";
9	import { consumeRateLimit } from "@/lib/rate-limit";
10	import { archivePatch, assertNotArchived } from "@/lib/soft-delete";
11	import { assertOrgScope } from "@/lib/tenant";
12	import * as commentRepo from "@/server/repositories/comment-repository";
13	import * as issueRepo from "@/server/repositories/issue-repository";
14	import * as memberRepo from "@/server/repositories/member-repository";
15	import {
16	  actorEnvelope,
17	  assertProjectLive,
18	  commentResource,
19	  issueResource,
20	  requireFound,
21	} from "./_support";
22	import type {
23	  CreateCommentInput,
24	  DeleteCommentInput,
25	  UpdateCommentInput,
26	} from "@/schemas/comment";
27	import type { Comment, CommentThreadNode } from "@/types/comment";
28	import type { IssueId, OrgId, UserId } from "@/types/common";
29	import type { Actor } from "@/types/member";
30	
31	/** How long after posting an author may still edit their own comment. */
32	const EDIT_WINDOW_MS = 15 * 60 * 1000;
33	
34	/** How many members are scanned when resolving `@handle` mentions. */
35	const MENTION_LOOKUP_LIMIT = 100;
36	
37	/** Token bucket protecting the comment thread from burst posting. */
38	const COMMENT_CREATE_BUCKET = "comment:create";
39	
40	/**
41	 * Posts a comment on a live issue. Mentions written as `@handle` in the body
42	 * are resolved against the org's members here, so the stored row and the
43	 * `comment.created` payload agree on who was mentioned — the notification
44	 * fan-out reads that list rather than re-parsing the markdown.
45	 */
46	export async function createComment(
47	  actor: Actor,
48	  input: CreateCommentInput,
49	): Promise<Comment> {
50	  assertOrgScope(actor, input.orgId);
51	
52	  const issue = requireFound(
53	    await issueRepo.findIssueById(input.orgId, input.issueId),
54	    "Issue",
55	    input.issueId,
56	  );
57	  assertCan(actor, "comment:create", issueResource(issue));
58	  assertNotArchived("Issue", issue.id, issue);
59	  await assertProjectLive(input.orgId, issue.projectId);
60	
61	  const verdict = await consumeRateLimit(input.orgId, COMMENT_CREATE_BUCKET);
62	  if (!verdict.allowed) {
63	    throw new Error(
64	      `Comment rate limit reached; try again after ${verdict.resetAt}`,
65	    );
66	  }
67	
68	  const mentionedUserIds = await resolveMentionedUsers(
69	    input.orgId,
70	    input.body,
71	    input.mentionedUserIds,
72	  );
73	
74	  const comment = await commentRepo.insertComment(
75	    { ...input, mentionedUserIds: [...mentionedUserIds] },
76	    actor.userId,
77	  );
78	
79	  await emit("comment.created", {
80	    ...actorEnvelope(actor),
81	    commentId: comment.id,
82	    issueId: comment.issueId,
83	    mentionedUserIds,
84	  });
85	
86	  return comment;
87	}
88	
89	/**
90	 * Edits are allowed inside a fifteen-minute window, or by anyone the role
91	 * matrix already lets update a comment. `can()` decides the second half —
92	 * this service only owns the time window.
93	 */
94	export async function updateComment(
95	  actor: Actor,
96	  input: UpdateCommentInput,
97	): Promise<Comment> {
98	  assertOrgScope(actor, input.orgId);
