import { describe, expect, it } from "vitest";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import * as issueService from "@/server/services/issue-service";
import * as commentService from "@/server/services/comment-service";
import * as attachmentService from "@/server/services/attachment-service";
import * as projectService from "@/server/services/project-service";
import { runOverdueIssueJob, resetOverdueTracking } from "@/server/jobs/overdue-issue-job";
import { subscribe } from "@/lib/event-bus";

useTemporaryDatabase();

describe("archived project freeze (scratch)", () => {
  it("freezes issue writes when archiveIssues=false, and restore lifts it", async () => {
    const tenant = await createTenant("freezescratch", "growth");

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Frozen candidate" }),
    );

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });

    let events = 0;
    const off = subscribe("issue.updated", () => { events += 1; });

    await expect(
      issueService.updateIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        title: "Changed?",
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    await expect(
      issueService.changeIssueStatus(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        status: "in_progress",
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    await expect(
      issueService.assignIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: tenant.actors.member.userId,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    await expect(
      issueService.archiveIssue(tenant.actors.admin, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    await expect(
      commentService.createComment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        body: "hello",
        parentId: null,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    await expect(
      attachmentService.addAttachment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        fileName: "x.png",
        sizeBytes: 100,
        contentType: "image/png",
        url: "https://example.com/x.png",
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    off();
    expect(events).toBe(0);

    // reads still work
    const read = await issueService.getIssue(tenant.actors.member, tenant.org.id, issue.id);
    expect(read.issue.id).toBe(issue.id);

    // restore lifts the freeze
    await projectService.restoreProject(tenant.actors.admin, tenant.org.id, tenant.project.id);
    const after = await issueService.updateIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      title: "Changed now",
    });
    expect(after.title).toBe("Changed now");
  });

  it("overdue sweep skips issues of an archived project, and restore lifts it", async () => {
    resetOverdueTracking();
    const tenant = await createTenant("freezeoverdue", "growth");

    const past = new Date(Date.now() - 60_000).toISOString();
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Overdue candidate",
        dueAt: past as never,
      }),
    );

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });

    const seen: string[] = [];
    const off = subscribe("issue.overdue", (payload) => { seen.push(payload.issueId); });

    await runOverdueIssueJob(new Date());
    expect(seen).not.toContain(issue.id);

    await projectService.restoreProject(tenant.actors.admin, tenant.org.id, tenant.project.id);
    await runOverdueIssueJob(new Date());
    off();
    expect(seen).toContain(issue.id);
  });
});

